function isVMProxy(obj) {
	const key = {};
	const proto = Object.getPrototypeOf(obj);
	if (!proto) return undefined;
	proto.isVMProxy = key;
	const proxy = obj.isVMProxy !== key;
	delete proto.isVMProxy;
	return proxy;
}

